<template><div><div class="section-head"><div><span class="eyebrow-dark">Products</span><h2>产品和设备型号</h2></div><el-button @click="loadAll">刷新</el-button></div><el-row :gutter="18"><el-col :md="12" :xs="24"><el-card shadow="never"><template #header>产品</template><el-table :data="products"><el-table-column prop="name" label="产品" /><el-table-column prop="product_code" label="编码" /><el-table-column prop="category" label="分类" /></el-table></el-card></el-col><el-col :md="12" :xs="24"><el-card shadow="never"><template #header>设备型号</template><el-table :data="models"><el-table-column prop="model_name" label="型号" /><el-table-column prop="model_code" label="编码" /><el-table-column prop="status" label="状态" /></el-table></el-card></el-col></el-row></div></template><script setup>import { onMounted, ref } from 'vue'; import { listResource } from '../api/resources'; const products=ref([]); const models=ref([]); async function loadAll(){ products.value=(await listResource('products')).data; models.value=(await listResource('device-models')).data } onMounted(loadAll)</script>
